//! What every spike shares: one engine connection, calls, and named checks.
//!
//! A spike answers a question in PLAN.md A0. Each check prints PASS or FAIL
//! with its reason, and the example exits non-zero when any check fails. Run
//! one with `cargo run -p bastion-spikes --example n1_engine` against `make up`.

use std::future::Future;
use std::time::Instant;

use anyhow::{anyhow, Result};
use iii_sdk::iii::WorkerMetadata;
use iii_sdk::protocol::TriggerRequest;
use iii_sdk::{register_worker, IIIClient, InitOptions};
use serde_json::Value;

pub const NAMESPACE: &str = "bastion";

pub fn engine_url() -> String {
    std::env::var("III_URL").unwrap_or_else(|_| "ws://127.0.0.1:49160".into())
}

pub fn connect(name: &str) -> IIIClient {
    let metadata = WorkerMetadata { name: name.into(), ..WorkerMetadata::default() };
    let options = InitOptions {
        metadata: Some(metadata),
        namespace: Some(NAMESPACE.into()),
        ..InitOptions::default()
    };
    register_worker(&engine_url(), options)
}

/// Call a function in this worker's namespace and wait for its answer.
pub async fn call(iii: &IIIClient, function_id: &str, payload: Value) -> Result<Value> {
    Ok(iii.trigger(TriggerRequest::new(function_id, payload)).await?)
}

/// Call a function the engine registers in `default`, such as `sandbox::*` or `engine::*`.
pub async fn call_default(iii: &IIIClient, function_id: &str, payload: Value, timeout_ms: u64) -> Result<Value> {
    let mut request = TriggerRequest::new(function_id, payload);
    request.timeout_ms = Some(timeout_ms);
    Ok(iii.trigger(request.namespace("default")).await?)
}

pub fn ensure(ok: bool, why: impl Into<String>) -> Result<()> {
    if ok { Ok(()) } else { Err(anyhow!(why.into())) }
}

#[derive(Default)]
pub struct Checks {
    failed: Vec<String>,
}

impl Checks {
    /// Run one check and report it. A failure never stops the run.
    pub async fn run<F: Future<Output = Result<String>>>(&mut self, name: &str, check: F) {
        let started = Instant::now();
        match check.await {
            Ok(detail) => println!("PASS  {name}  ({} ms)  {detail}", started.elapsed().as_millis()),
            Err(error) => {
                println!("FAIL  {name}: {error:#}");

//! Bastion's first page (PLAN.md A0, N6): the engine's state through a command,
//! and each push from the core as it arrives.

use leptos::prelude::*;
use leptos::task::spawn_local;
use serde::Serialize;
use wasm_bindgen::prelude::*;

#[wasm_bindgen]
extern "C" {
    #[wasm_bindgen(js_namespace = ["window", "__TAURI__", "core"])]
    async fn invoke(cmd: &str, args: JsValue) -> JsValue;
    #[wasm_bindgen(js_namespace = ["window", "__TAURI__", "event"])]
    async fn listen(event: &str, handler: &Closure<dyn FnMut(JsValue)>) -> JsValue;
}

#[derive(Serialize)]
struct Seen {
    event: String,
}

#[component]
pub fn App() -> impl IntoView {
    let (engine, set_engine) = signal(String::from("…"));
    let (last, set_last) = signal(String::from("nothing yet"));
    spawn_local(async move {
        let answer = invoke("engine_status", JsValue::NULL).await;
        set_engine.set(answer.as_string().unwrap_or_else(|| format!("{answer:?}")));
    });
    spawn_local(async move {
        let handler = Closure::new(move |event: JsValue| {
            let payload = js_sys::Reflect::get(&event, &"payload".into()).unwrap_or(JsValue::NULL);
            let text = js_sys::JSON::stringify(&payload).map(String::from).unwrap_or_default();
            set_last.set(text.clone());
            spawn_local(async move {
                let args = serde_wasm_bindgen::to_value(&Seen { event: text }).unwrap();
                invoke("seen", args).await;
            });
        });
        listen("changed", &handler).await;
        handler.forget(); // the page lives as long as the window
    });

    view! {
        <main class="min-h-screen p-8 grid gap-4 content-start">
            <h1 class="m-0 text-2xl font-extrabold">"Bastion"</h1>
            <section class="rounded-xl border border-line bg-panel p-4">
                <h2 class="m-0 text-sm font-semibold text-muted">"Engine"</h2>
                <p data-testid="engine">{engine}</p>
            </section>
            <section class="rounded-xl border border-line bg-panel p-4">
                <h2 class="m-0 text-sm font-semibold text-muted">"Last push from the engine"</h2>
                <p data-testid="last"><code class="text-link">{last}</code></p>
            </section>
            <button class="w-fit rounded-lg bg-primary px-4 py-2 font-semibold text-white hover:bg-primary-hover">
                "Purple"
            </button>
        </main>
    }
}
