//! The Commands seam (PLAN.md §6.2): every command the view calls and every
//! event the app emits, with their types. The view and the app both depend on
//! this crate, and on nothing of each other's.

use serde::{Deserialize, Serialize};

/// Command names, so the view and the app cannot drift apart.
pub mod command {
    pub const ENGINE_STATUS: &str = "engine_status";
}

/// Event names the app emits to the page (D10).
pub mod event {
    /// Carries an [`EngineStatus`](super::EngineStatus) each time the link changes.
    pub const ENGINE_CHANGED: &str = "engine-changed";
}

/// The app's link to the engine.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Link {
    Connecting,
    Up,
    Reconnecting,
    Down,
}

/// What the page shows about the engine.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct EngineStatus {
    pub url: String,
    pub link: Link,
    /// The count of registered functions, when the link is up and the engine answered.
    pub functions: Option<usize>,
}

//! The Engine seam (PLAN.md §6.2). This module is the only code in the app that
//! imports `iii-sdk` (D19). Everything else holds an `Arc<dyn Engine>`.

mod iii;
#[cfg(test)]
pub mod fake;

use std::future::Future;
use std::pin::Pin;

use bastion_protocol::Link;
use serde_json::Value;

pub use iii::IiiEngine;

/// The namespace the engine registers its own functions in, such as `engine::*`.
pub const DEFAULT_NAMESPACE: &str = "default";

pub type Call<'a> = Pin<Box<dyn Future<Output = Result<Value, String>> + Send + 'a>>;

pub trait Engine: Send + Sync {
    /// The engine's address, as the profile gave it.
    fn url(&self) -> &str;
    /// The link as it is now. The SDK reconnects by itself.
    fn link(&self) -> Link;
    /// Call one function and wait for its answer.
    fn call<'a>(&'a self, namespace: &'a str, function_id: &'a str, payload: Value) -> Call<'a>;
}

//! The Engine seam on a real engine, through `iii-sdk`.

use bastion_protocol::Link;
use iii_sdk::iii::WorkerMetadata;
use iii_sdk::protocol::TriggerRequest;
use iii_sdk::{IIIClient, IIIConnectionState, InitOptions, register_worker};
use serde_json::Value;

use super::{Call, Engine};

const CALL_TIMEOUT_MS: u64 = 5_000;

pub struct IiiEngine {
    url: String,
    client: IIIClient,
}

impl IiiEngine {
    pub fn connect(url: &str) -> Self {
        let options = InitOptions {
            metadata: Some(WorkerMetadata { name: "bastion-app".into(), ..WorkerMetadata::default() }),
            namespace: Some("bastion".into()),
            ..InitOptions::default()
        };
        Self { url: url.into(), client: register_worker(url, options) }
    }
}

impl Engine for IiiEngine {
    fn url(&self) -> &str {
        &self.url
    }

    fn link(&self) -> Link {
        match self.client.get_connection_state() {
            IIIConnectionState::Connecting => Link::Connecting,
            IIIConnectionState::Connected => Link::Up,
            IIIConnectionState::Reconnecting => Link::Reconnecting,
            IIIConnectionState::Disconnected | IIIConnectionState::Failed => Link::Down,
        }
    }

    fn call<'a>(&'a self, namespace: &'a str, function_id: &'a str, payload: Value) -> Call<'a> {
        Box::pin(async move {
            let mut request = TriggerRequest::new(function_id, payload);
            request.timeout_ms = Some(CALL_TIMEOUT_MS);
            self.client.trigger(request.namespace(namespace)).await.map_err(|e| e.to_string())
        })
    }
}

//! An in-memory engine for tests: canned answers by function id, and a record
//! of every call.

use std::collections::HashMap;
use std::sync::Mutex;

use bastion_protocol::Link;
use serde_json::Value;

use super::{Call, Engine};

pub struct FakeEngine {
    pub link: Mutex<Link>,
    answers: HashMap<String, Result<Value, String>>,
    pub calls: Mutex<Vec<(String, String, Value)>>,
}

impl FakeEngine {
    pub fn new(link: Link) -> Self {
        Self { link: Mutex::new(link), answers: HashMap::new(), calls: Mutex::new(Vec::new()) }
    }

    pub fn answer(mut self, function_id: &str, answer: Result<Value, String>) -> Self {
        self.answers.insert(function_id.into(), answer);
        self
    }
}

impl Engine for FakeEngine {
    fn url(&self) -> &str {
        "ws://fake"
    }

    fn link(&self) -> Link {
        *self.link.lock().unwrap()
    }

    fn call<'a>(&'a self, namespace: &'a str, function_id: &'a str, payload: Value) -> Call<'a> {
        self.calls.lock().unwrap().push((namespace.into(), function_id.into(), payload));
        let answer = self
            .answers
            .get(function_id)
            .cloned()
            .unwrap_or_else(|| Err(format!("function_not_found: {function_id}")));
        Box::pin(async move { answer })
    }
}

//! Commands and events about the engine link.

use std::sync::Arc;
use std::time::Duration;

use bastion_protocol::{EngineStatus, Link, event};
use serde_json::json;
use tauri::{AppHandle, Emitter, State};

use crate::engine::{DEFAULT_NAMESPACE, Engine};

/// How often the watcher reads the link. The SDK offers no listener for it.
// ponytail: a local read every half second; switch to a listener if iii-sdk adds one.
const LINK_POLL: Duration = Duration::from_millis(500);

pub async fn status(engine: &dyn Engine) -> EngineStatus {
    let link = engine.link();
    let functions = match link {
        Link::Up => engine
            .call(DEFAULT_NAMESPACE, "engine::functions::list", json!({}))
            .await
            .ok()
            .and_then(|out| out["functions"].as_array().map(Vec::len)),
        _ => None,
    };
    EngineStatus { url: engine.url().into(), link, functions }
}

#[tauri::command]
pub async fn engine_status(engine: State<'_, Arc<dyn Engine>>) -> Result<EngineStatus, ()> {
    Ok(status(engine.inner().as_ref()).await)
}

/// Emit the engine status to the page each time the link changes.
pub fn watch(app: AppHandle, engine: Arc<dyn Engine>) {
    tauri::async_runtime::spawn(async move {
        let mut last = None;
        loop {
            let link = engine.link();
            if last != Some(link) {
                last = Some(link);
                let _ = app.emit(event::ENGINE_CHANGED, status(engine.as_ref()).await);
            }
            tokio::time::sleep(LINK_POLL).await;
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::fake::FakeEngine;

    #[test]
    fn up_link_counts_the_engine_functions() {
        let engine = FakeEngine::new(Link::Up)
            .answer("engine::functions::list", Ok(json!({ "functions": [{}, {}, {}] })));
        let status = tauri::async_runtime::block_on(status(&engine));
        assert_eq!(status, EngineStatus { url: "ws://fake".into(), link: Link::Up, functions: Some(3) });
        assert_eq!(engine.calls.lock().unwrap()[0].0, DEFAULT_NAMESPACE);
    }

    #[test]
    fn down_link_makes_no_call() {
        let engine = FakeEngine::new(Link::Down);
        let status = tauri::async_runtime::block_on(status(&engine));
        assert_eq!(status.functions, None);
        assert!(engine.calls.lock().unwrap().is_empty());
    }

    #[test]
    fn a_failed_call_still_reports_the_link() {
        let engine = FakeEngine::new(Link::Up).answer("engine::functions::list", Err("timeout".into()));
        let status = tauri::async_runtime::block_on(status(&engine));
        assert_eq!((status.link, status.functions), (Link::Up, None));
    }
}

//! Bastion's Rust core. The pages reach the engine only through these commands
//! (PLAN.md D9), and the engine reaches the pages only as events (D10).

mod commands;
mod engine;

use std::sync::Arc;

use engine::{Engine, IiiEngine};

/// The local engine. A profile replaces this default in A1 (D12).
const ENGINE_URL: &str = "ws://127.0.0.1:49160";

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .setup(|app| {
            let url = std::env::var("III_URL").unwrap_or_else(|_| ENGINE_URL.into());
            let engine: Arc<dyn Engine> = Arc::new(IiiEngine::connect(&url));
            commands::engine::watch(app.handle().clone(), engine.clone());
            app.manage(engine);
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![commands::engine::engine_status])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

