//! The Machine seam (PLAN.md §6.2): the programs, files and platform of this
//! machine. Doctor and the stack routine reach the OS only through it.

use std::fs::{self, OpenOptions};
use std::os::unix::process::CommandExt;
use std::path::Path;
use std::process::{Command, Stdio};

/// What a program printed and how it ended.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Output {
    pub success: bool,
    /// Standard output, then standard error.
    pub text: String,
}

pub trait Machine: Send + Sync {
    /// Run a program to its end. `Err` means it could not start at all.
    fn run(&self, program: &str, args: &[&str], dir: Option<&Path>) -> Result<Output, String>;
    /// Start a program that outlives the app, with its output appended to `log`.
    fn spawn(&self, program: &str, args: &[&str], dir: &Path, log: &Path) -> Result<u32, String>;
    fn read(&self, path: &Path) -> Result<String, String>;
    fn exists(&self, path: &Path) -> bool;
    /// `std::env::consts::OS` and `ARCH`.
    fn platform(&self) -> (&'static str, &'static str);
}

pub struct ThisMachine;

impl Machine for ThisMachine {
    fn run(&self, program: &str, args: &[&str], dir: Option<&Path>) -> Result<Output, String> {
        let mut command = Command::new(program);
        command.args(args);
        if let Some(dir) = dir {
            command.current_dir(dir);
        }
        let out = command.output().map_err(|e| format!("{program}: {e}"))?;
        let text = String::from_utf8_lossy(&out.stdout).into_owned()
            + &String::from_utf8_lossy(&out.stderr);
        Ok(Output {
            success: out.status.success(),
            text,
        })
    }

    // ponytail: the child is never waited on, so if it exits while the app runs it stays a zombie until the app quits.
    fn spawn(&self, program: &str, args: &[&str], dir: &Path, log: &Path) -> Result<u32, String> {
        if let Some(parent) = log.parent() {
            fs::create_dir_all(parent).map_err(|e| format!("{}: {e}", parent.display()))?;
        }
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(log)
            .map_err(|e| format!("{}: {e}", log.display()))?;
        let err = file.try_clone().map_err(|e| e.to_string())?;
        Command::new(program)
            .args(args)
            .current_dir(dir)
            .stdin(Stdio::null())
            .stdout(file)
            .stderr(err)
            // Its own process group, so a signal to the app does not reach it.
            .process_group(0)
            .spawn()
            .map(|child| child.id())
            .map_err(|e| format!("{program}: {e}"))
    }

    fn read(&self, path: &Path) -> Result<String, String> {
        fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))
    }

    fn exists(&self, path: &Path) -> bool {
        path.exists()
    }

    fn platform(&self) -> (&'static str, &'static str) {
        (std::env::consts::OS, std::env::consts::ARCH)
    }
}

#[cfg(test)]
pub mod fake {
    use std::collections::HashMap;
    use std::path::{Path, PathBuf};
    use std::sync::Mutex;

    use super::{Machine, Output};

    /// Canned runs by program name, files by path, and a fixed platform. A
    /// program given several answers returns them in turn, then keeps the last.
    pub struct FakeMachine {
        runs: Mutex<HashMap<String, Vec<Result<Output, String>>>>,
        pub files: HashMap<PathBuf, String>,
        pub platform: (&'static str, &'static str),
        /// Every run and spawn, as `program arg arg`.
        pub calls: Mutex<Vec<String>>,
    }

    impl FakeMachine {
        pub fn new() -> Self {
            Self {
                runs: Mutex::new(HashMap::new()),
                files: HashMap::new(),
                platform: ("macos", "aarch64"),
                calls: Mutex::new(Vec::new()),
            }
        }

        fn answer(self, program: &str, answer: Result<Output, String>) -> Self {
            self.runs
                .lock()
                .unwrap()
                .entry(program.into())
                .or_default()
                .push(answer);
            self
        }

        pub fn run_ok(self, program: &str, text: &str) -> Self {
            let output = Output {
                success: true,
                text: text.into(),
            };
            self.answer(program, Ok(output))
        }

        pub fn run_fails(self, program: &str, text: &str) -> Self {
            let output = Output {
                success: false,
                text: text.into(),
            };
            self.answer(program, Ok(output))
        }

        pub fn file(mut self, path: &str, text: &str) -> Self {
            self.files.insert(path.into(), text.into());
            self
        }

        pub fn called(&self, prefix: &str) -> bool {
            self.calls.lock().unwrap().iter().any(|c| c.starts_with(prefix))
        }
    }

    impl Machine for FakeMachine {
        fn run(&self, program: &str, args: &[&str], _dir: Option<&Path>) -> Result<Output, String> {
            self.calls
                .lock()
                .unwrap()
                .push(format!("{program} {}", args.join(" ")));
            let mut runs = self.runs.lock().unwrap();
            match runs.get_mut(program) {
                Some(answers) if answers.len() > 1 => answers.remove(0),
                Some(answers) => answers[0].clone(),
                None => Err(format!("{program}: not found")),
            }
        }

        fn spawn(&self, program: &str, args: &[&str], _dir: &Path, _log: &Path) -> Result<u32, String> {
            self.calls
                .lock()
                .unwrap()
                .push(format!("spawn {program} {}", args.join(" ")));
            Ok(4242)
        }

        fn read(&self, path: &Path) -> Result<String, String> {
            self.files
                .get(path)
                .cloned()
                .ok_or_else(|| format!("{}: not found", path.display()))
        }

        fn exists(&self, path: &Path) -> bool {
            self.files.contains_key(path)
        }

        fn platform(&self) -> (&'static str, &'static str) {
            self.platform
        }
    }
}

//! The stack routine (PLAN.md A1, D13): start, attach to, and stop the compose
//! project in the profile's checkout. `iii ps --json` is the source of truth.

use std::path::{Path, PathBuf};
use std::time::Duration;

use bastion_protocol::{StackState, StackStatus, StartRefused};
use serde::Deserialize;

use crate::doctor::{self, COMPOSE_FILE};
use crate::engine::Engine;
use crate::machine::Machine;

/// How long a started daemon has to show up in `iii ps`.
const START_WAIT: Duration = Duration::from_secs(10);
const START_POLL: Duration = Duration::from_millis(250);

/// Where this profile's stack lives.
pub struct Stack {
    pub checkout: PathBuf,
    /// The engine port the profile points at.
    pub port: u16,
    pub log: PathBuf,
}

#[derive(Deserialize)]
struct Process {
    pid: u32,
    kind: String,
    #[serde(default)]
    ports: Vec<u16>,
    compose_file: Option<String>,
}

impl Stack {
    pub fn compose_file(&self) -> PathBuf {
        self.checkout.join(COMPOSE_FILE)
    }

    pub fn status(&self, machine: &dyn Machine) -> Result<StackStatus, String> {
        Ok(StackStatus {
            state: self.state(machine)?,
            compose_file: self.compose_file().display().to_string(),
            log: self.log.display().to_string(),
        })
    }

    fn state(&self, machine: &dyn Machine) -> Result<StackState, String> {
        let out = machine.run("iii", &["ps", "--json"], None)?;
        if !out.success {
            return Err(format!("iii ps: {}", out.text.trim()));
        }
        let processes: Vec<Process> =
            serde_json::from_str(&out.text).map_err(|e| format!("iii ps --json: {e}"))?;
        let ours = self.compose_file().display().to_string();
        if processes
            .iter()
            .any(|p| p.kind == "compose" && p.compose_file.as_deref() == Some(ours.as_str()))
        {
            return Ok(StackState::Running);
        }
        Ok(processes
            .into_iter()
            .find(|p| p.kind == "engine" && p.ports.contains(&self.port))
            .map_or(StackState::Stopped, |p| StackState::Taken {
                pid: p.pid,
                compose_file: p.compose_file,
            }))
    }

    /// Attach to a running stack, or run Doctor and start one.
    pub async fn start(
        &self,
        machine: &dyn Machine,
        engine: &dyn Engine,
    ) -> Result<StackStatus, StartRefused> {
        let failed = |message: String| StartRefused::Failed { message };
        match self.state(machine).map_err(failed)? {
            StackState::Running => return self.status(machine).map_err(failed),
            StackState::Taken { pid, compose_file } => {
                return Err(StartRefused::Taken { pid, compose_file });
            }
            StackState::Stopped => {}
        }
        let report = doctor::run(machine, engine, &self.checkout).await;
        if !report.ready() {
            return Err(StartRefused::Doctor { report });
        }
        let file = self.compose_file().display().to_string();
        machine
            .spawn("iii", &["compose", "--up", "-f", &file], &self.checkout, &self.log)
            .map_err(failed)?;
        let mut waited = Duration::ZERO;
        while waited < START_WAIT {
            if self.state(machine).map_err(failed)? == StackState::Running {
                return self.status(machine).map_err(failed);
            }
            tokio::time::sleep(START_POLL).await;
            waited += START_POLL;
        }
        Err(failed(format!(
            "the compose daemon did not appear within {}s; see {}",
            START_WAIT.as_secs(),
            self.log.display()
        )))
    }

    pub fn stop(&self, machine: &dyn Machine) -> Result<StackStatus, String> {
        let file = self.compose_file().display().to_string();
        let out = machine.run("iii", &["kill", "--compose", &file], Some(&self.checkout))?;
        if !out.success {
            return Err(format!("iii kill: {}", out.text.trim()));
        }
        self.status(machine)
    }
}

/// The port in an engine URL such as `ws://127.0.0.1:49160`.
pub fn port(url: &str) -> Option<u16> {
    url.rsplit(':').next()?.trim_end_matches('/').parse().ok()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::fake::FakeEngine;
    use crate::machine::fake::FakeMachine;
    use bastion_protocol::Link;

    const COMPOSE: &str = "containers:\n  a:\n    worker: package://a\n    version: \"1.2.3\"\n";

    fn stack() -> Stack {
        Stack {
            checkout: "/repo".into(),
            port: 49160,
            log: "/logs/compose.log".into(),
        }
    }

    fn ps(rows: &str) -> String {
        format!("[{rows}]")
    }

    const OURS: &str = r#"{"pid":7,"kind":"compose","ports":[49160],"compose_file":"/repo/worker-compose.yaml"}"#;
    const OTHER: &str = r#"{"pid":9,"kind":"engine","ports":[49160],"compose_file":"/elsewhere/worker-compose.yaml"}"#;

    fn ready_machine() -> FakeMachine {
        FakeMachine::new()
            .run_ok("iii", "0.25.0")
            .run_ok("gh", "ok")
            .file("/repo/worker-compose.yaml", COMPOSE)
    }

    fn start(machine: &FakeMachine) -> Result<StackStatus, StartRefused> {
        let engine = FakeEngine::new(Link::Down);
        tauri::async_runtime::block_on(stack().start(machine, &engine))
    }

    #[test]
    fn port_comes_from_the_engine_url() {
        assert_eq!(port("ws://127.0.0.1:49160"), Some(49160));
        assert_eq!(port("ws://box"), None);
    }

    #[test]
    fn a_running_stack_is_attached_not_started_twice() {
        let machine = FakeMachine::new().run_ok("iii", &ps(OURS));
        assert_eq!(start(&machine).unwrap().state, StackState::Running);
        assert!(!machine.called("spawn"));
    }

    #[test]
    fn a_port_held_by_another_project_is_refused_with_its_owner() {
        let machine = FakeMachine::new().run_ok("iii", &ps(OTHER));
        let refused = start(&machine).unwrap_err();
        assert_eq!(
            refused,
            StartRefused::Taken {
                pid: 9,
                compose_file: Some("/elsewhere/worker-compose.yaml".into())
            }
        );
        assert!(!machine.called("spawn"));
    }

    #[test]
    fn a_failed_doctor_stops_the_start() {
        // `iii ps` answers, then `iii --version` reports the wrong iii.
        let machine = FakeMachine::new()
            .run_ok("iii", &ps(""))
            .run_ok("iii", "0.23.0")
            .run_ok("gh", "ok")
            .file("/repo/worker-compose.yaml", COMPOSE);
        assert!(matches!(start(&machine), Err(StartRefused::Doctor { .. })));
        assert!(!machine.called("spawn"));
    }

    #[test]
    fn a_stopped_stack_starts_in_the_checkout() {
        // `iii ps` (stopped), `iii --version`, then `iii ps` (running) from then on.
        let machine = FakeMachine::new()
            .run_ok("iii", &ps(""))
            .run_ok("iii", "0.25.0")
            .run_ok("iii", &ps(OURS))
            .run_ok("gh", "ok")
            .file("/repo/worker-compose.yaml", COMPOSE);
        assert_eq!(start(&machine).unwrap().state, StackState::Running);
        assert!(machine.called("spawn iii compose --up -f /repo/worker-compose.yaml"));
    }

    #[test]
    fn stop_kills_this_compose_project_only() {
        let machine = ready_machine();
        let _ = stack().stop(&machine);
        assert!(machine.called("iii kill --compose /repo/worker-compose.yaml"));
    }
}

//! Commands for the stack: status, start or attach, and stop.

use std::sync::Arc;

use bastion_protocol::{StackStatus, StartRefused};
use tauri::State;

use crate::engine::Engine;
use crate::machine::Machine;
use crate::stack::Stack;

#[tauri::command]
pub fn stack_status(
    stack: State<'_, Stack>,
    machine: State<'_, Arc<dyn Machine>>,
) -> Result<StackStatus, String> {
    stack.status(machine.inner().as_ref())
}

#[tauri::command]
pub async fn stack_start(
    stack: State<'_, Stack>,
    machine: State<'_, Arc<dyn Machine>>,
    engine: State<'_, Arc<dyn Engine>>,
) -> Result<StackStatus, StartRefused> {
    stack
        .start(machine.inner().as_ref(), engine.inner().as_ref())
        .await
}

#[tauri::command]
pub fn stack_stop(
    stack: State<'_, Stack>,
    machine: State<'_, Arc<dyn Machine>>,
) -> Result<StackStatus, String> {
    stack.stop(machine.inner().as_ref())
}

