//! The view's side of the Commands seam: typed calls and events over Tauri's
//! global API (PLAN.md D9, D10).

use serde::Serialize;
use serde::de::DeserializeOwned;
use wasm_bindgen::prelude::*;

#[wasm_bindgen]
extern "C" {
    #[wasm_bindgen(js_namespace = ["window", "__TAURI__", "core"], js_name = invoke, catch)]
    async fn invoke_js(cmd: &str, args: JsValue) -> Result<JsValue, JsValue>;
    #[wasm_bindgen(js_namespace = ["window", "__TAURI__", "event"], js_name = listen)]
    async fn listen_js(event: &str, handler: &Closure<dyn FnMut(JsValue)>) -> JsValue;
}

/// Call a command. `E` is the command's typed error; a string error reads as one too.
pub async fn call<T: DeserializeOwned, E: DeserializeOwned>(cmd: &str, args: impl Serialize) -> Result<T, Failure<E>> {
    let args = serde_wasm_bindgen::to_value(&args).map_err(|e| Failure::Broken(e.to_string()))?;
    match invoke_js(cmd, args).await {
        Ok(value) => serde_wasm_bindgen::from_value(value).map_err(|e| Failure::Broken(e.to_string())),
        Err(value) => Err(serde_wasm_bindgen::from_value::<E>(value.clone())
            .map(Failure::Refused)
            .unwrap_or_else(|_| Failure::Broken(format!("{value:?}")))),
    }
}

/// Why a call did not return its value.
pub enum Failure<E> {
    /// The command answered with its typed error.
    Refused(E),
    /// The call itself failed: unknown command, or an answer that did not parse.
    Broken(String),
}

impl Failure<String> {
    pub fn text(self) -> String {
        match self {
            Failure::Refused(text) | Failure::Broken(text) => text,
        }
    }
}

/// Run `on_event` with each payload of `event`, for the life of the page.
pub fn listen<T: DeserializeOwned + 'static>(event: &'static str, on_event: impl Fn(T) + 'static) {
    leptos::task::spawn_local(async move {
        let handler = Closure::new(move |e: JsValue| {
            let payload = js_sys::Reflect::get(&e, &"payload".into()).unwrap_or(JsValue::NULL);
            if let Ok(value) = serde_wasm_bindgen::from_value(payload) {
                on_event(value);
            }
        });
        listen_js(event, &handler).await;
        handler.forget(); // the page lives as long as the window
    });
}

/// No arguments.
#[derive(Serialize)]
pub struct None {}

//! The shell (PLAN.md A1): the sidebar, the page it shows, and the question on
//! quit while the stack runs.

use bastion_protocol::{ActiveProfile, command, event};
use leptos::prelude::*;
use leptos::task::spawn_local;
use serde::Serialize;

use crate::ipc::{self, None};
use crate::pages::{engine::EnginePage, settings::SettingsPage};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Page {
    Floor,
    Inbox,
    Engine,
    Settings,
}

const PAGES: [(Page, &str); 4] = [
    (Page::Floor, "Floor"),
    (Page::Inbox, "Inbox"),
    (Page::Engine, "Engine"),
    (Page::Settings, "Settings"),
];

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct Quit {
    stop_stack: bool,
}

#[component]
pub fn App() -> impl IntoView {
    let (page, set_page) = signal(Page::Engine);
    let (profile, set_profile) = signal(String::new());
    let (asking, set_asking) = signal(false);
    spawn_local(async move {
        if let Ok(p) = ipc::call::<ActiveProfile, String>(command::PROFILE, None {}).await {
            set_profile.set(p.name);
        }
    });
    ipc::listen(event::QUIT_REQUESTED, move |()| set_asking.set(true));
    let quit = move |stop_stack: bool| {
        spawn_local(async move {
            let _ = ipc::call::<(), String>(command::QUIT, Quit { stop_stack }).await;
        });
    };

    view! {
        <a href="#main" class="sr-only focus:not-sr-only focus:absolute focus:m-2 focus:rounded focus:bg-primary focus:px-3 focus:py-2 focus:text-white">
            "Skip to content"
        </a>
        <div class="grid min-h-screen grid-cols-[200px_1fr]">
            <nav aria-label="Main" class="flex flex-col gap-1 border-r border-line bg-panel p-3">
                <p class="m-0 mb-3 px-2 text-lg font-extrabold">"Bastion"</p>
                {PAGES.map(|(p, label)| view! {
                    <button
                        class="rounded-lg px-2 py-1.5 text-left hover:bg-line aria-[current=page]:bg-primary aria-[current=page]:text-white"
                        aria-current=move || (page.get() == p).then_some("page")
                        on:click=move |_| set_page.set(p)
                    >{label}</button>
                })}
                <p class="mt-auto px-2 text-xs text-muted">{profile}</p>
            </nav>
            <main id="main" tabindex="-1" class="p-8">
                {move || match page.get() {
                    Page::Floor => later("Floor", "A3").into_any(),
                    Page::Inbox => later("Inbox", "A3").into_any(),
                    Page::Engine => view! { <EnginePage /> }.into_any(),
                    Page::Settings => view! { <SettingsPage /> }.into_any(),
                }}
            </main>
        </div>
        <Show when=move || asking.get()>
            <div class="fixed inset-0 grid place-items-center bg-black/60">
                <div role="dialog" aria-modal="true" aria-labelledby="quit-title" class="grid max-w-sm gap-3 rounded-xl border border-line bg-panel p-5">
                    <h2 id="quit-title" class="m-0 text-lg font-bold">"The stack is running"</h2>
                    <p class="m-0 text-muted">"Stop it with the app, or keep it running for the next start to attach to?"</p>
                    <div class="flex flex-wrap gap-2">
                        <button class="rounded-lg bg-primary px-3 py-2 font-semibold text-white hover:bg-primary-hover" on:click=move |_| quit(false)>"Keep it running"</button>
                        <button class="rounded-lg border border-line px-3 py-2 hover:bg-line" on:click=move |_| quit(true)>"Stop the stack"</button>
                        <button class="rounded-lg px-3 py-2 text-muted hover:bg-line" on:click=move |_| set_asking.set(false)>"Cancel"</button>
                    </div>
                </div>
            </div>
        </Show>
    }
}

/// A page a later phase builds.
fn later(title: &'static str, phase: &'static str) -> impl IntoView {
    view! {
        <h1 class="mt-0 text-2xl font-bold">{title}</h1>
        <p class="text-muted">{format!("Not built yet: {phase} builds this page.")}</p>
    }
}

//! The Engine page (PLAN.md A1): the link, the stack with Start and Stop, and
//! Doctor. A2 adds the console below it.

use bastion_protocol::{
    Check, CheckState, DoctorReport, EngineStatus, Link, StackState, StackStatus, StartRefused,
    command, event,
};
use leptos::prelude::*;
use leptos::task::spawn_local;

use crate::ipc::{self, Failure, None};

fn describe_link(status: &EngineStatus) -> String {
    match (status.link, status.functions) {
        (Link::Up, Some(n)) => format!("Up at {}, {n} functions.", status.url),
        (Link::Up, None) => format!("Up at {}.", status.url),
        (Link::Connecting, _) => format!("Connecting to {}.", status.url),
        (Link::Reconnecting, _) => format!("Reconnecting to {}.", status.url),
        (Link::Down, _) => format!("Down: {} does not answer.", status.url),
    }
}

fn describe_stack(status: &StackStatus) -> String {
    match &status.state {
        StackState::Stopped => "Stopped.".into(),
        StackState::Running => format!("Running from {}.", status.compose_file),
        StackState::Taken { pid, compose_file } => format!(
            "Port taken by engine pid {pid} ({}).",
            compose_file.as_deref().unwrap_or("not a compose project")
        ),
    }
}

fn describe_refusal(refused: StartRefused) -> String {
    match refused {
        StartRefused::Doctor { .. } => "Doctor found a required check that failed. See below.".into(),
        StartRefused::Taken { pid, compose_file } => format!(
            "Not started: engine pid {pid} already holds the port ({}).",
            compose_file.as_deref().unwrap_or("not a compose project")
        ),
        StartRefused::Failed { message } => format!("Not started: {message}"),
    }
}

#[component]
pub fn EnginePage() -> impl IntoView {
    let (link, set_link) = signal(String::from("…"));
    let (stack, set_stack) = signal(None::<StackStatus>);
    let (note, set_note) = signal(String::new());
    let (busy, set_busy) = signal(false);
    let (report, set_report) = signal(None::<DoctorReport>);

    let refresh_stack = move || {
        spawn_local(async move {
            match ipc::call::<StackStatus, String>(command::STACK_STATUS, None {}).await {
                Ok(s) => set_stack.set(Some(s)),
                Err(e) => set_note.set(e.text()),
            }
        });
    };
    let run_doctor = move || {
        spawn_local(async move {
            if let Ok(r) = ipc::call::<DoctorReport, String>(command::DOCTOR, None {}).await {
                set_report.set(Some(r));
            }
        });
    };
    spawn_local(async move {
        if let Ok(s) = ipc::call::<EngineStatus, String>(command::ENGINE_STATUS, None {}).await {
            set_link.set(describe_link(&s));
        }
    });
    ipc::listen(event::ENGINE_CHANGED, move |s: EngineStatus| {
        set_link.set(describe_link(&s));
        refresh_stack();
        run_doctor();
    });
    refresh_stack();
    run_doctor();

    let start = move |_| {
        set_busy.set(true);
        set_note.set("Starting: Doctor first, then the stack.".into());
        spawn_local(async move {
            match ipc::call::<StackStatus, StartRefused>(command::STACK_START, None {}).await {
                Ok(s) => {
                    set_note.set(String::new());
                    set_stack.set(Some(s));
                }
                Err(Failure::Refused(StartRefused::Doctor { report })) => {
                    set_report.set(Some(report.clone()));
                    set_note.set(describe_refusal(StartRefused::Doctor { report }));
                }
                Err(Failure::Refused(r)) => set_note.set(describe_refusal(r)),
                Err(Failure::Broken(e)) => set_note.set(e),
            }
            set_busy.set(false);
        });
    };
    let stop = move |_| {
        set_busy.set(true);
        spawn_local(async move {
            match ipc::call::<StackStatus, String>(command::STACK_STOP, None {}).await {
                Ok(s) => {
                    set_note.set(String::new());
                    set_stack.set(Some(s));
                }
                Err(e) => set_note.set(e.text()),
            }
            set_busy.set(false);
        });
    };
    let running = move || matches!(stack.get().map(|s| s.state), Some(StackState::Running));

    view! {
        <h1 class="mt-0 text-2xl font-bold">"Engine"</h1>
        <section class="mb-4 grid gap-2 rounded-xl border border-line bg-panel p-4">
            <h2 class="m-0 text-sm font-semibold text-muted">"Link"</h2>
            <p class="m-0" data-testid="link">{link}</p>
        </section>
        <section class="mb-4 grid gap-2 rounded-xl border border-line bg-panel p-4">
            <h2 class="m-0 text-sm font-semibold text-muted">"Stack"</h2>
            <p class="m-0" data-testid="stack">{move || stack.get().map(|s| describe_stack(&s)).unwrap_or_else(|| "…".into())}</p>
            <p class="m-0 text-muted" role="status">{note}</p>
            <div class="flex gap-2">
                <button class="rounded-lg bg-primary px-3 py-2 font-semibold text-white hover:bg-primary-hover disabled:opacity-50"
                    disabled=move || busy.get() || running() on:click=start>"Start"</button>
                <button class="rounded-lg border border-line px-3 py-2 hover:bg-line disabled:opacity-50"
                    disabled=move || busy.get() || !running() on:click=stop>"Stop"</button>
            </div>
        </section>
        <section class="grid gap-2 rounded-xl border border-line bg-panel p-4">
            <div class="flex items-center justify-between">
                <h2 class="m-0 text-sm font-semibold text-muted">"Doctor"</h2>
                <button class="rounded-lg border border-line px-3 py-1 text-sm hover:bg-line" on:click=move |_| run_doctor()>"Run again"</button>
            </div>
            <ul class="m-0 grid list-none gap-2 p-0">
                {move || report.get().map(|r| r.checks.into_iter().map(check_row).collect_view())}
            </ul>
        </section>
    }
}

fn check_row(check: Check) -> impl IntoView {
    let (mark, color) = match check.state {
        CheckState::Pass => ("Pass", "text-ok"),
        CheckState::Warn => ("Warn", "text-warn"),
        CheckState::Fail => ("Fail", "text-bad"),
        CheckState::Skipped => ("Skipped", "text-muted"),
    };
    view! {
        <li class="grid grid-cols-[72px_1fr] gap-x-3">
            <span class={format!("font-semibold {color}")}>{mark}</span>
            <span><strong>{check.name}</strong>": "{check.detail}</span>
            {check.fix.map(|fix| view! { <span></span><span class="text-muted">{fix}</span> })}
        </li>
    }
}

//! The Settings page (PLAN.md A1): the active profile. A7 adds the rest.

use bastion_protocol::{ActiveProfile, command};
use leptos::prelude::*;
use leptos::task::spawn_local;

use crate::ipc::{self, None};

#[component]
pub fn SettingsPage() -> impl IntoView {
    let (profile, set_profile) = signal(None::<ActiveProfile>);
    spawn_local(async move {
        if let Ok(p) = ipc::call::<ActiveProfile, String>(command::PROFILE, None {}).await {
            set_profile.set(Some(p));
        }
    });
    let row = |label: &'static str, value: String| {
        view! { <dt class="text-muted">{label}</dt><dd class="m-0 break-all">{value}</dd> }
    };
    view! {
        <h1 class="mt-0 text-2xl font-bold">"Settings"</h1>
        <section class="grid gap-2 rounded-xl border border-line bg-panel p-4">
            <h2 class="m-0 text-sm font-semibold text-muted">"Profile"</h2>
            {move || profile.get().map(|p| view! {
                <dl class="m-0 grid grid-cols-[120px_1fr] gap-x-3 gap-y-1">
                    {row("Name", p.name)}
                    {row("Kind", p.kind)}
                    {row("Engine", p.engine_url)}
                    {row("Checkout", p.checkout)}
                    {row("File", p.file)}
                </dl>
            })}
        </section>
    }
}

